import { useState, type FormEvent } from 'react';
import {
  JxAlert,
  JxButton,
  JxInputField,
  JxSelect,
  JxSwitch,
} from '@jinx-ui/react';

const ROLES = [
  { value: 'viewer', label: 'Наблюдатель', meta: 'только чтение' },
  { value: 'editor', label: 'Редактор', meta: 'может менять' },
  { value: 'admin', label: 'Администратор', meta: 'полный доступ' },
];

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

export default function TeamInviteForm() {
  const [email, setEmail] = useState('');
  const [touched, setTouched] = useState(false);
  const [role, setRole] = useState('editor');
  const [notify, setNotify] = useState(true);
  const [invited, setInvited] = useState<string | null>(null);

  const emailValid = EMAIL_RE.test(email.trim());
  const showError = touched && !emailValid;

  const submit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!emailValid) {
      setTouched(true);
      return;
    }
    setInvited(email.trim());
    setEmail('');
    setTouched(false);
  };

  return (
    <div style={{ display: 'grid', gap: '16px', maxWidth: '420px' }}>
      {invited && (
        <JxAlert intent="success" title="Приглашение отправлено">
          <div style={{ display: 'grid', gap: '8px', justifyItems: 'start' }}>
            <span>
              Мы отправили приглашение на {invited}
              {notify ? ' и уведомили команду.' : '.'}
            </span>
            <JxButton variant="ghost" size="sm" onClick={() => setInvited(null)}>
              Закрыть
            </JxButton>
          </div>
        </JxAlert>
      )}

      <form onSubmit={submit} style={{ display: 'grid', gap: '16px' }} noValidate>
        <JxInputField
          label="Почта участника"
          type="email"
          required
          placeholder="name@company.com"
          value={email}
          onChange={(event) => setEmail(event.target.value)}
          onBlur={() => setTouched(true)}
          helperText="Приглашение придёт на этот адрес и будет действовать 7 дней"
          errorText={showError ? 'Введите адрес вида name@company.com' : undefined}
        />

        <JxSelect
          label="Роль в команде"
          options={ROLES}
          value={role}
          onValueChange={setRole}
          placeholder="Выберите роль"
        />

        <JxSwitch
          label="Отправить уведомление команде"
          checked={notify}
          onChange={(event) => setNotify(event.target.checked)}
        />

        <JxButton type="submit" variant="primary" disabled={!emailValid}>
          Отправить приглашение
        </JxButton>
      </form>
    </div>
  );
}

